import{_ as t,o as d,a,a2 as r}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Backend Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/backend.md","filePath":"architecture/backend.md","lastUpdated":1790143103000}'),o={name:"architecture/backend.md"};function s(i,e,n,c,h,l){return d(),a("div",null,e[0]||(e[0]=[r(`<h1 id="backend-architecture" tabindex="-1">Backend Architecture <a class="header-anchor" href="#backend-architecture" aria-label="Permalink to &quot;Backend Architecture&quot;">​</a></h1><p>This page maps Bagisto&#39;s server side: how a request travels through the application, the building blocks every package uses, and what each of the 42 core packages holds. Each section links to the guide that explains its topic in full.</p><h2 id="how-a-request-is-handled" tabindex="-1">How a Request Is Handled <a class="header-anchor" href="#how-a-request-is-handled" aria-label="Permalink to &quot;How a Request Is Handled&quot;">​</a></h2><ol><li><p><code>public/index.php</code> boots the application from <code>bootstrap/app.php</code>. Laravel loads every service provider in <code>bootstrap/providers.php</code>, and Concord loads the modules listed in <code>config/concord.php</code>.</p></li><li><p>The global middleware added in <code>bootstrap/app.php</code> runs: <code>Webkul\\Core\\Http\\Middleware\\SecureHeaders</code> sets the security headers, and <code>Webkul\\Installer\\Http\\Middleware\\CanInstall</code> sends every request to <code>/install</code> until Bagisto is installed.</p></li><li><p>The route decides which middleware stack applies:</p><table tabindex="0"><thead><tr><th>Area</th><th>Routes</th><th>Middleware</th></tr></thead><tbody><tr><td>Admin</td><td><code>packages/Webkul/Admin/src/Routes/</code>, prefixed with <code>config(&#39;app.admin_url&#39;)</code></td><td><code>web</code> and Bagisto&#39;s maintenance check; every page except sign-in, password reset and two-factor verification also passes <code>admin</code> (the <code>Bouncer</code>: sign-in, account status, permissions, two-factor authentication) and <code>NoCacheMiddleware</code></td></tr><tr><td>Storefront</td><td><code>packages/Webkul/Shop/src/Routes/web.php</code> and <code>api.php</code></td><td><code>web</code>, the <code>shop</code> group (<code>Theme</code>, <code>Locale</code>, <code>Currency</code>) and the maintenance check; the home, category, product, CMS, search, compare and contact pages add <code>cache.response</code> for the full page cache</td></tr><tr><td>Payment gateways</td><td><code>Routes/</code> in the Stripe, PayU, Razorpay, PhonePe and PayGlocal packages, and <code>Http/routes.php</code> in Paypal</td><td>Set by each gateway</td></tr><tr><td>Web installer</td><td><code>packages/Webkul/Installer/src/Routes/web.php</code></td><td><code>web</code>, with the installer&#39;s own session and locale middleware</td></tr></tbody></table></li><li><p>The controller reads and writes data through repositories, which return Concord models. Writes are wrapped in <code>before</code> and <code>after</code> events. Controllers, repositories, DataGrids and listeners are resolved from the container, so a package can bind a subclass in place of a core one.</p></li><li><p>The response is usually a Blade view. The Theme package resolves <code>shop::</code> and <code>admin::</code> views against the active theme before the package&#39;s own views (<a href="./../theme-development/creating-store-theme.html#how-views-are-resolved">how views are resolved</a>), and <code>view_render_event()</code> calls in the templates let other packages add markup.</p></li><li><p>In the browser, the layout loads the Vite bundle and mounts the Vue app; see <a href="./frontend.html">Frontend Architecture</a>.</p></li></ol><h2 id="models-contracts-and-proxies" tabindex="-1">Models, Contracts and Proxies <a class="header-anchor" href="#models-contracts-and-proxies" aria-label="Permalink to &quot;Models, Contracts and Proxies&quot;">​</a></h2><p>Bagisto uses <a href="https://github.com/artkonekt/concord" target="_blank" rel="noreferrer">Concord</a> so that one package can replace another package&#39;s model without editing it. Every entity has three parts:</p><table tabindex="0"><thead><tr><th>Part</th><th>Example</th><th>Role</th></tr></thead><tbody><tr><td>Contract</td><td><code>Webkul\\Category\\Contracts\\Category</code></td><td>An empty interface that names the entity</td></tr><tr><td>Model</td><td><code>Webkul\\Category\\Models\\Category</code></td><td>The Eloquent model, which implements the contract</td></tr><tr><td>Proxy</td><td><code>Webkul\\Category\\Models\\CategoryProxy</code></td><td>Resolves to whichever model is registered for the contract</td></tr></tbody></table><p>A package lists its models in the <code>$models</code> array of its <code>ModuleServiceProvider</code>, which in most core packages extends <code>Webkul\\Core\\Providers\\CoreModuleServiceProvider</code>. Code that crosses packages refers to the contract or the proxy, never the concrete model: a repository&#39;s <code>model()</code> returns the contract, and a relation uses the proxy, as in <code>RMAStatusProxy::modelClass()</code>. See <a href="./../package-development/models.html">Models</a>, including <a href="./../package-development/models.html#extending-a-core-model">Extending a Core Model</a>.</p><p><a id="repository-pattern-in-bagisto"></a></p><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h2><p>All database access goes through repositories. A repository extends <code>Webkul\\Core\\Eloquent\\Repository</code>, which extends Prettus&#39;s <code>BaseRepository</code>, and its <code>model()</code> method returns the contract of the model it works with, such as <code>&#39;Webkul\\Attribute\\Contracts\\AttributeGroup&#39;</code>.</p><ul><li>On top of Prettus&#39;s methods, the base class adds <code>findOneByField()</code>, <code>findOneWhere()</code>, <code>findOrFail()</code>, <code>sum()</code>, <code>avg()</code> and <code>getModel()</code>.</li><li>It caches reads, controlled by <code>config/repository.php</code> and invalidated through a per-repository generation token; see <a href="./../advanced/cache-strategy.html#repository-cache">Repository Cache</a>.</li><li>Controllers, listeners and jobs receive repositories through constructor injection. The one place allowed to build a query directly is a DataGrid&#39;s <code>prepareQueryBuilder()</code>.</li></ul><p>See <a href="./../package-development/repositories.html">Repositories</a>.</p><h2 id="events-and-view-render-events" tabindex="-1">Events and View Render Events <a class="header-anchor" href="#events-and-view-render-events" aria-label="Permalink to &quot;Events and View Render Events&quot;">​</a></h2><p>Bagisto&#39;s events are dot-delimited strings, usually fired in <code>before</code> and <code>after</code> pairs around a write:</p><p><strong>File:</strong> <code>packages/Webkul/Admin/src/Http/Controllers/Catalog/ProductController.php</code></p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;catalog.product.update.before&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $id);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$product </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">productRepository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($request</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), $id);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;catalog.product.update.after&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $product);</span></span></code></pre></div><p>Each package maps listeners to event names in the <code>$listen</code> array of its own <code>EventServiceProvider</code>; see <a href="./../advanced/event-listeners.html">Event Listeners</a> for the events core fires.</p><p>Core templates also call <code>view_render_event()</code> at named points, such as <code>bagisto.shop.layout.body.after</code>. A package adds markup there by listening for the event and adding a template to the <code>Webkul\\Theme\\ViewRenderEventManager</code>; see <a href="./../advanced/view-render-events.html">View Render Events</a>.</p><h2 id="menus-permissions-and-configuration" tabindex="-1">Menus, Permissions and Configuration <a class="header-anchor" href="#menus-permissions-and-configuration" aria-label="Permalink to &quot;Menus, Permissions and Configuration&quot;">​</a></h2><p>The admin menu, the permissions, the system configuration fields and several registries are PHP arrays that packages merge into shared configuration keys with <code>mergeConfigFrom()</code>, in their service provider&#39;s <code>register()</code> method:</p><table tabindex="0"><thead><tr><th>Config key</th><th>Core entries</th><th>Used for</th></tr></thead><tbody><tr><td><code>menu.admin</code></td><td><code>Admin/src/Config/menu.php</code></td><td>The admin sidebar, read through <code>menu()</code> (<code>Webkul\\Core\\Menu</code>), which hides items the admin has no permission for</td></tr><tr><td><code>menu.customer</code></td><td><code>Shop/src/Config/menu.php</code></td><td>The customer account menu</td></tr><tr><td><code>acl</code></td><td><code>Admin/src/Config/acl.php</code></td><td>Role permissions, read through <code>acl()</code> (<code>Webkul\\Core\\Acl</code>); the <code>Bouncer</code> maps each route name to a permission key</td></tr><tr><td><code>core</code></td><td><code>Admin/src/Config/system.php</code></td><td>System configuration fields, read through <code>system_config()</code> (<code>Webkul\\Core\\SystemConfig</code>); saved values come from <code>core()-&gt;getConfigData($field, $channel, $locale)</code></td></tr><tr><td><code>payment_methods</code></td><td><code>Config/payment-methods.php</code> in Payment and each gateway</td><td>Payment methods</td></tr><tr><td><code>carriers</code></td><td><code>Shipping/src/Config/carriers.php</code></td><td>Shipping methods</td></tr><tr><td><code>product_types</code></td><td><code>Product/src/Config/product_types.php</code></td><td>Product types</td></tr><tr><td><code>importers</code></td><td><code>DataTransfer/src/Config/importers.php</code></td><td>Import types</td></tr></tbody></table><p>In core, the Admin package defines the menu items, permissions and configuration fields for every package. Your package merges its own files into the same keys; see <a href="./../package-development/menu.html">Menu</a>, <a href="./../package-development/access-control-list.html">Access Control List</a> and <a href="./../package-development/system-configuration.html">System Configuration</a>. <code>mergeConfigFrom()</code> keeps an entry that is already set, so a package changes the class behind a core payment method, carrier, product type or importer from its provider&#39;s <code>boot()</code> instead; see <a href="./../product-type-development/understanding-product-type-configuration.html#overriding-a-core-type">Overriding a Core Type</a>.</p><h2 id="datagrids" tabindex="-1">DataGrids <a class="header-anchor" href="#datagrids" aria-label="Permalink to &quot;DataGrids&quot;">​</a></h2><p>Admin listings extend <code>Webkul\\DataGrid\\DataGrid</code> and implement <code>prepareQueryBuilder()</code> and <code>prepareColumns()</code>, and optionally <code>prepareActions()</code> and <code>prepareMassActions()</code>. The controller returns <code>datagrid(ProductDataGrid::class)-&gt;process()</code> for the listing&#39;s AJAX request, and <code>process()</code> applies the requested filters, sorting, pagination and export. See <a href="./../package-development/datagrid.html">DataGrid</a>.</p><h2 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h2><p>Packages define global helper functions in their <code>src/Http/helpers.php</code>:</p><table tabindex="0"><thead><tr><th>Helper</th><th>Returns</th><th>Package</th></tr></thead><tbody><tr><td><code>core()</code></td><td><code>Webkul\\Core\\Core</code>: channels, locales, currencies and configuration values</td><td>Core</td></tr><tr><td><code>menu()</code>, <code>acl()</code>, <code>system_config()</code></td><td>The menu, ACL and system configuration registries</td><td>Core</td></tr><tr><td><code>db_grammar()</code></td><td>SQL fragments for the active database (MySQL, MariaDB or PostgreSQL)</td><td>Core</td></tr><tr><td><code>clean_content()</code></td><td>HTML passed through HTMLPurifier, with Blade syntax removed</td><td>Core</td></tr><tr><td><code>bouncer()</code></td><td>Permission checks for the signed-in admin</td><td>User</td></tr><tr><td><code>two_factor_authentication()</code></td><td><code>Webkul\\User\\TwoFactorAuthentication</code></td><td>User</td></tr><tr><td><code>cart()</code></td><td>The current cart (<code>Webkul\\Checkout\\Cart</code>)</td><td>Checkout</td></tr><tr><td><code>payment()</code>, <code>shipping()</code></td><td>The payment and shipping method registries</td><td>Payment, Shipping</td></tr><tr><td><code>datagrid()</code></td><td>An instance of the given DataGrid class</td><td>DataGrid</td></tr><tr><td><code>themes()</code></td><td>The theme registry (<code>Webkul\\Theme\\Themes</code>)</td><td>Theme</td></tr><tr><td><code>bagisto_asset()</code></td><td>The URL of a file a theme ships</td><td>Theme</td></tr><tr><td><code>bagisto_theme_storage()</code></td><td><code>Webkul\\Theme\\ThemeStorage</code>, for media a theme section stores</td><td>Theme</td></tr><tr><td><code>view_render_event()</code></td><td>The rendered output of a view render event</td><td>Theme</td></tr><tr><td><code>image_manager()</code>, <code>image_urls()</code></td><td>Laravel&#39;s image manager, and the resized URLs of an image</td><td>ImageCache</td></tr><tr><td><code>product_image()</code>, <code>product_video()</code>, <code>product_toolbar()</code></td><td>Product media and listing toolbar helpers</td><td>Product</td></tr><tr><td><code>magic_ai()</code></td><td>The Generative AI (Magic AI) service</td><td>MagicAI</td></tr></tbody></table><p><a href="./../advanced/understanding-core-class.html">Understanding the Core Class</a> documents <code>core()</code> method by method.</p><p><a id="modular-design-in-bagisto"></a><a id="available-packages-in-bagisto"></a></p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>Each package is autoloaded from <code>composer.json</code>, registers its service provider in <code>bootstrap/providers.php</code> and, when it has models, its <code>ModuleServiceProvider</code> in <code>config/concord.php</code>; <a href="./overview.html#how-a-package-is-wired-in">How a Package Is Wired In</a> has the details, and <a href="./overview.html#inside-a-package">Inside a Package</a> its directories. DebugBar, FPC, ImageCache, Installer, MagicAI, PhonePe and SocialShare have no module provider, and Admin, PayGlocal, Payment, Paypal, PayU, Razorpay, Rule, Shipping, Shop and Stripe have one with an empty <code>$models</code> list. <code>bootstrap/providers.php</code> also lists <code>Webkul\\Core\\Providers\\EnvValidatorServiceProvider</code>, which stops the application when <code>DB_PREFIX</code> contains anything other than letters, digits and underscores.</p><table tabindex="0"><thead><tr><th>Package</th><th>What it holds</th></tr></thead><tbody><tr><td>Admin</td><td>The admin: routes, controllers, views, DataGrids, reporting, the command palette, and the menu, ACL and configuration fields</td></tr><tr><td>Attribute</td><td>Attributes, attribute options, groups and families</td></tr><tr><td>BookingProduct</td><td>The booking product type: default, appointment, event, rental and table slots, and bookings</td></tr><tr><td>CartRule</td><td>Cart price rules, coupons and coupon usage</td></tr><tr><td>CatalogRule</td><td>Catalog price rules and their per-product prices</td></tr><tr><td>Category</td><td>The nested-set category tree and its translations</td></tr><tr><td>Checkout</td><td>The cart: items, addresses, payment and shipping rates</td></tr><tr><td>CMS</td><td>CMS pages and their translations</td></tr><tr><td>Core</td><td>Channels, locales, currencies, exchange rates, countries and states, saved configuration and newsletter subscribers; the <code>core()</code> helpers, the menu, ACL and configuration registries, the database grammar, the dynamic SMTP mailer and the storage driver</td></tr><tr><td>Customer</td><td>Customers, groups, addresses, notes, wishlists, compare items and the customer captcha</td></tr><tr><td>DataGrid</td><td>The DataGrid base class, column types, saved filters and export</td></tr><tr><td>DataTransfer</td><td>Imports: the importer registry, import batches and queued jobs</td></tr><tr><td>DebugBar</td><td>DebugBar integration, with a collector that groups models, views and queries by package</td></tr><tr><td>EUWithdrawal</td><td>EU right-of-withdrawal requests</td></tr><tr><td>FPC</td><td>The full page cache on <code>spatie/laravel-responsecache</code>: cache profile, hasher, replacers and invalidation listeners</td></tr><tr><td>GDPR</td><td>Customer data requests</td></tr><tr><td>ImageCache</td><td>Resized images served at <code>cache/{template}/{path}</code>, and the template registry</td></tr><tr><td>Installer</td><td><code>bagisto:install</code>, the web installer and the seeders</td></tr><tr><td>Inventory</td><td>Inventory sources</td></tr><tr><td>MagicAI</td><td>Generative AI (Magic AI) through the Laravel AI SDK</td></tr><tr><td>Marketing</td><td>Campaigns, email templates, events, search terms, search synonyms and URL rewrites</td></tr><tr><td>Notification</td><td>Admin notifications for orders</td></tr><tr><td>Omnibus</td><td>Price snapshots and the 30-day lowest price for the EU Omnibus directive</td></tr><tr><td>PayGlocal</td><td>The PayGlocal payment gateway</td></tr><tr><td>Payment</td><td>The base payment class, cash on delivery, money transfer and the <code>payment_methods</code> registry</td></tr><tr><td>Paypal</td><td>PayPal Smart Button and PayPal Standard</td></tr><tr><td>PayU</td><td>The PayU payment gateway</td></tr><tr><td>PhonePe</td><td>The PhonePe payment gateway</td></tr><tr><td>Product</td><td>Products, product types, attribute values, images, videos, reviews, customer group prices, customizable options, inventories, the flat table, and the price, inventory, flat and search indexers</td></tr><tr><td>Razorpay</td><td>The Razorpay payment gateway</td></tr><tr><td>RMA</td><td>Returns: requests, items, reasons, rules, statuses, custom fields and messages</td></tr><tr><td>Rule</td><td>The condition engine that cart rules and catalog rules share</td></tr><tr><td>Sales</td><td>Orders, invoices, shipments, refunds, transactions and purchased downloadable links</td></tr><tr><td>Shipping</td><td>The base carrier class, flat rate and free shipping, and the <code>carriers</code> registry</td></tr><tr><td>Shop</td><td>The storefront: routes, controllers, views, Blade components, the customer account, the storefront&#39;s JSON API and WebMCP</td></tr><tr><td>Sitemap</td><td>XML sitemaps</td></tr><tr><td>SocialLogin</td><td>Customer sign-in through social accounts</td></tr><tr><td>SocialShare</td><td>Share links for products</td></tr><tr><td>Stripe</td><td>The Stripe payment gateway</td></tr><tr><td>Tax</td><td>Tax categories, tax rates and the mapping between them</td></tr><tr><td>Theme</td><td>The theme registry and view finder, <code>@bagistoVite</code>, Appearance sections, theme storage and view render events</td></tr><tr><td>User</td><td>Admins, roles, the <code>Bouncer</code> middleware and two-factor authentication</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./overview.html">Architecture Overview</a>: the project structure and the extension points.</li><li><a href="./frontend.html">Frontend Architecture</a>: how Blade, Vue.js and Vite fit together.</li><li><a href="./../package-development/getting-started.html">Package Development</a>: build a package with these building blocks.</li><li><a href="./../advanced/event-listeners.html">Event Listeners</a>: the events core fires and how to listen for them.</li></ul>`,35)]))}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
